-- Lote 1/4: 25 questões fáceis por obra (50 no total).
-- Inserção idempotente por enunciado; códigos são gerados pela sequência existente.
WITH incoming AS (
  SELECT * FROM jsonb_to_recordset($questions$[{"book":"livro_espiritos","statement":"Segundo a questão 1, como os Espíritos definem Deus?","option_a":"Uma criação da imaginação humana.","option_b":"Um ser material que habita um planeta.","option_c":"Uma força limitada pela natureza.","option_d":"Um conjunto de espíritos superiores.","option_e":"A inteligência suprema, causa primária de todas as coisas.","correct_option":"E","explanation":"A resposta da obra apresenta Deus como inteligência suprema e causa primária de tudo o que existe.","reference":"O Livro dos Espíritos, Livro Primeiro, cap. I, questão 1.","difficulty":"facil","active":true},{"book":"livro_espiritos","statement":"O que significa, na obra, dizer que Deus é eterno?","option_a":"Que teve início antes da criação do Universo.","option_b":"Que depende da matéria para existir.","option_c":"Que existe apenas enquanto há vida.","option_d":"Que muda conforme as épocas.","option_e":"Que não teve começo nem terá fim.","correct_option":"E","explanation":"A eternidade é apresentada como ausência de começo e de fim.","reference":"O Livro dos Espíritos, Livro Primeiro, cap. I, questão 13.","difficulty":"facil","active":true},{"book":"livro_espiritos","statement":"Qual é a ideia central da resposta à pergunta sobre o infinito?","option_a":"Tudo o que tem limite é infinito.","option_b":"O infinito é apenas o espaço visível.","option_c":"O infinito é sinônimo de eternidade apenas.","option_d":"O infinito é uma dimensão material.","option_e":"Aquilo que não tem começo nem fim é infinito.","correct_option":"E","explanation":"Kardec registra a definição de infinito como aquilo que não tem começo nem fim; a ideia é aplicada ao que ultrapassa os limites conhecidos.","reference":"O Livro dos Espíritos, Livro Primeiro, cap. I, questão 2.","difficulty":"facil","active":true},{"book":"livro_espiritos","statement":"Segundo a obra, qual é a principal prova da existência de Deus?","option_a":"A tradição de um único povo.","option_b":"A existência de templos antigos.","option_c":"A opinião dos filósofos.","option_d":"A observação exclusiva dos fenômenos celestes.","option_e":"O princípio de que não há efeito sem causa.","correct_option":"E","explanation":"A resposta relaciona a existência de Deus ao princípio de que todo efeito inteligente deve ter uma causa inteligente.","reference":"O Livro dos Espíritos, Livro Primeiro, cap. I, questão 4.","difficulty":"facil","active":true},{"book":"livro_espiritos","statement":"Como a obra descreve a matéria em relação ao Espírito?","option_a":"Como o princípio inteligente do Universo.","option_b":"Como sinônimo de perispírito.","option_c":"Como algo inexistente.","option_d":"Como a única realidade possível.","option_e":"Como um dos elementos gerais, distinto do Espírito.","correct_option":"E","explanation":"O livro distingue Espírito e matéria como elementos gerais do Universo, sem reduzir um ao outro.","reference":"O Livro dos Espíritos, Livro Primeiro, cap. II, questão 27.","difficulty":"facil","active":true},{"book":"livro_espiritos","statement":"Qual é a finalidade principal da encarnação dos Espíritos?","option_a":"Separá-los para sempre dos demais Espíritos.","option_b":"Impedir qualquer progresso moral.","option_c":"Conceder privilégios permanentes a alguns.","option_d":"Apagar definitivamente sua individualidade.","option_e":"Conduzi-los à perfeição por meio das experiências corporais.","correct_option":"E","explanation":"A encarnação é apresentada como meio de progresso e aperfeiçoamento dos Espíritos.","reference":"O Livro dos Espíritos, Livro Segundo, cap. II, questão 132.","difficulty":"facil","active":true},{"book":"livro_espiritos","statement":"O que é o perispírito na explicação espírita da obra?","option_a":"O corpo físico depois da morte.","option_b":"Uma parte do planeta de origem.","option_c":"O princípio vital dos animais.","option_d":"A memória intelectual do encarnado.","option_e":"Um fluido que envolve o Espírito e serve de ligação com o corpo.","correct_option":"E","explanation":"O perispírito é descrito como envoltório semimaterial do Espírito e elemento de ligação com o corpo.","reference":"O Livro dos Espíritos, Livro Segundo, cap. I, questão 93.","difficulty":"facil","active":true},{"book":"livro_espiritos","statement":"Qual é a condição dos Espíritos entre uma encarnação e outra?","option_a":"Deixam de existir até o próximo nascimento.","option_b":"Permanecem necessariamente no mesmo local.","option_c":"Perdem toda consciência de si.","option_d":"Transformam-se em matéria inerte.","option_e":"Vivem no estado de erraticidade, aguardando nova existência corporal.","correct_option":"E","explanation":"A erraticidade é o estado dos Espíritos não encarnados, entre duas existências corporais.","reference":"O Livro dos Espíritos, Livro Segundo, cap. VI, questão 224.","difficulty":"facil","active":true},{"book":"livro_espiritos","statement":"Segundo a obra, o que é a reencarnação?","option_a":"A vida exclusiva no mundo espiritual.","option_b":"A ressurreição do mesmo corpo físico.","option_c":"A transferência da alma para um animal em todos os casos.","option_d":"O desaparecimento da individualidade.","option_e":"A volta do Espírito à vida corporal em novo corpo.","correct_option":"E","explanation":"A reencarnação é o retorno do Espírito à existência corporal, em outro corpo.","reference":"O Livro dos Espíritos, Livro Segundo, cap. IV, questão 166.","difficulty":"facil","active":true},{"book":"livro_espiritos","statement":"Qual é a razão apresentada para a pluralidade das existências?","option_a":"Punir eternamente o Espírito.","option_b":"Repetir exatamente a mesma existência.","option_c":"Manter os Espíritos sem liberdade.","option_d":"Evitar a vida espiritual.","option_e":"Permitir progresso e reparação ao longo de várias experiências.","correct_option":"E","explanation":"As múltiplas existências oferecem oportunidades de desenvolvimento e reajuste moral.","reference":"O Livro dos Espíritos, Livro Segundo, cap. IV, questão 167.","difficulty":"facil","active":true},{"book":"livro_espiritos","statement":"O que a obra afirma sobre a individualidade da alma após a morte?","option_a":"Ela se dissolve imediatamente.","option_b":"Ela passa a integrar a matéria do corpo.","option_c":"Ela se transforma em outra pessoa.","option_d":"Ela só existe na lembrança dos vivos.","option_e":"Ela permanece individual, conservando sua identidade.","correct_option":"E","explanation":"A obra sustenta a continuidade da individualidade do Espírito após a morte do corpo.","reference":"O Livro dos Espíritos, Livro Segundo, cap. III, questão 150.","difficulty":"facil","active":true},{"book":"livro_espiritos","statement":"Na visão da obra, o esquecimento do passado durante a encarnação serve principalmente para quê?","option_a":"Impedir qualquer aprendizado.","option_b":"Eliminar a responsabilidade moral.","option_c":"Apagar a história universal.","option_d":"Fazer o Espírito perder sua identidade essencial.","option_e":"Permitir novas experiências sem o peso direto das lembranças anteriores.","correct_option":"E","explanation":"O esquecimento das existências anteriores favorece uma nova experiência, sem que lembranças explícitas condicionem continuamente o indivíduo.","reference":"O Livro dos Espíritos, Livro Segundo, cap. VII, questão 392.","difficulty":"facil","active":true},{"book":"livro_espiritos","statement":"Como a obra caracteriza a lei natural?","option_a":"É restrita às práticas religiosas externas.","option_b":"É uma convenção criada por cada governo.","option_c":"Aplica-se somente aos Espíritos desencarnados.","option_d":"Muda conforme a vontade individual.","option_e":"É a lei de Deus, destinada ao bem de todos.","correct_option":"E","explanation":"A lei natural é apresentada como lei divina, universal e orientadora do bem.","reference":"O Livro dos Espíritos, Livro Terceiro, cap. I, questão 614.","difficulty":"facil","active":true},{"book":"livro_espiritos","statement":"Qual é a finalidade da prece segundo o capítulo sobre a lei de adoração?","option_a":"Substituir toda ação moral.","option_b":"Evitar qualquer dificuldade da vida.","option_c":"Garantir riqueza material imediata.","option_d":"Obrigar os Espíritos a obedecer aos encarnados.","option_e":"Aproximar a criatura de Deus e elevar o pensamento.","correct_option":"E","explanation":"A prece é tratada como forma de elevar o pensamento e estabelecer relação com Deus.","reference":"O Livro dos Espíritos, Livro Terceiro, cap. II, questão 659.","difficulty":"facil","active":true},{"book":"livro_espiritos","statement":"Como a obra entende o trabalho?","option_a":"Uma punição sem utilidade.","option_b":"Uma atividade exclusiva dos encarnados.","option_c":"Uma obrigação limitada ao esforço físico.","option_d":"Uma prática contrária ao desenvolvimento espiritual.","option_e":"Uma necessidade para o progresso e a conservação da vida.","correct_option":"E","explanation":"O trabalho é apresentado como lei natural e meio de desenvolvimento, não apenas como esforço corporal.","reference":"O Livro dos Espíritos, Livro Terceiro, cap. III, questão 674.","difficulty":"facil","active":true},{"book":"livro_espiritos","statement":"O que a obra ensina sobre a vida em sociedade?","option_a":"É dispensável para o progresso humano.","option_b":"Deve ser evitada por todos.","option_c":"Só tem valor para fins econômicos.","option_d":"É contrária à liberdade individual.","option_e":"É uma necessidade natural para o progresso e o auxílio mútuo.","correct_option":"E","explanation":"A vida social permite o progresso, a troca de experiências e a assistência recíproca.","reference":"O Livro dos Espíritos, Livro Terceiro, cap. VII, questão 766.","difficulty":"facil","active":true},{"book":"livro_espiritos","statement":"Segundo a lei de conservação, o que deve orientar o uso dos bens terrenos?","option_a":"A privação absoluta como regra universal.","option_b":"A busca ilimitada pelo luxo.","option_c":"A rejeição de todo recurso material.","option_d":"A acumulação sem finalidade.","option_e":"O equilíbrio entre necessidades reais e excessos.","correct_option":"E","explanation":"A lei de conservação valoriza o uso adequado dos recursos necessários à vida, sem abuso nem excesso.","reference":"O Livro dos Espíritos, Livro Terceiro, cap. V, questões 702–717.","difficulty":"facil","active":true},{"book":"livro_espiritos","statement":"O que a obra indica como sinal do progresso moral?","option_a":"A superioridade econômica sobre os outros.","option_b":"O predomínio da força física.","option_c":"A capacidade de impor crenças.","option_d":"O aumento do orgulho individual.","option_e":"A prática da justiça, do amor e da caridade.","correct_option":"E","explanation":"O progresso moral se expressa na vivência das virtudes e no respeito ao próximo.","reference":"O Livro dos Espíritos, Livro Terceiro, cap. VIII, questão 793.","difficulty":"facil","active":true},{"book":"livro_espiritos","statement":"Qual é a relação entre liberdade e responsabilidade moral na obra?","option_a":"A liberdade elimina toda responsabilidade.","option_b":"A intenção nunca tem importância.","option_c":"Somente os Espíritos puros respondem por seus atos.","option_d":"A responsabilidade depende apenas da lei civil.","option_e":"A liberdade de agir traz responsabilidade pelas escolhas.","correct_option":"E","explanation":"A liberdade de escolha é acompanhada pela responsabilidade moral sobre os próprios atos.","reference":"O Livro dos Espíritos, Livro Terceiro, cap. X, questões 843–850.","difficulty":"facil","active":true},{"book":"livro_espiritos","statement":"O que a obra ensina sobre a caridade?","option_a":"É apenas dar dinheiro aos necessitados.","option_b":"É uma prática reservada a instituições.","option_c":"É favorecer somente familiares.","option_d":"É cumprir rituais sem mudança interior.","option_e":"É benevolência para com todos, indulgência para as imperfeições alheias e perdão das ofensas.","correct_option":"E","explanation":"A definição de caridade da obra abrange benevolência, indulgência e perdão.","reference":"O Livro dos Espíritos, Livro Terceiro, cap. XI, questão 886.","difficulty":"facil","active":true},{"book":"livro_espiritos","statement":"Qual é a orientação apresentada sobre o orgulho?","option_a":"É indispensável para o progresso.","option_b":"É uma virtude quando acompanhado de riqueza.","option_c":"É sinal de superioridade espiritual.","option_d":"É necessário para conquistar respeito.","option_e":"É um obstáculo ao aperfeiçoamento moral.","correct_option":"E","explanation":"O orgulho é tratado como imperfeição que dificulta a humildade e o progresso moral.","reference":"O Livro dos Espíritos, Livro Terceiro, cap. XII, questões 913–917.","difficulty":"facil","active":true},{"book":"livro_espiritos","statement":"O que a obra diz sobre a igualdade natural dos seres humanos?","option_a":"Somente alguns povos possuem alma.","option_b":"As diferenças sociais provam superioridade espiritual permanente.","option_c":"A dignidade depende da posição econômica.","option_d":"A desigualdade de direitos é uma lei natural imutável.","option_e":"Todos possuem a mesma origem espiritual e estão sujeitos às leis divinas.","correct_option":"E","explanation":"A igualdade essencial decorre da origem comum e da condição de Espíritos em progresso.","reference":"O Livro dos Espíritos, Livro Terceiro, cap. IX, questões 803–806.","difficulty":"facil","active":true},{"book":"livro_espiritos","statement":"Como a obra relaciona inteligência e instinto?","option_a":"São exatamente a mesma faculdade.","option_b":"O instinto é sempre adquirido pelo estudo.","option_c":"A inteligência é exclusiva dos animais.","option_d":"O instinto desaparece em todos os seres humanos.","option_e":"São faculdades distintas, embora possam coexistir nos seres vivos.","correct_option":"E","explanation":"A obra distingue o instinto, ligado a ações necessárias e espontâneas, da inteligência, sem negar sua coexistência.","reference":"O Livro dos Espíritos, Livro Primeiro, cap. IV, questões 71–75.","difficulty":"facil","active":true},{"book":"livro_espiritos","statement":"Segundo a obra, o que ocorre com o Espírito após uma existência corporal?","option_a":"É destruído junto com o corpo.","option_b":"Retorna ao mundo espiritual, conservando sua individualidade.","option_c":"Permanece preso ao cadáver para sempre.","option_d":"Recomeça sem qualquer experiência anterior.","option_e":"Deixa de ter consciência.","correct_option":"B","explanation":"A morte encerra a vida orgânica, mas não destrói o Espírito, que retorna ao mundo espiritual.","reference":"O Livro dos Espíritos, Livro Segundo, cap. III, questões 149–152.","difficulty":"facil","active":true},{"book":"livro_espiritos","statement":"Qual é a função das provas e expiações no processo evolutivo, conforme a obra?","option_a":"Impedir definitivamente o progresso.","option_b":"Estabelecer privilégios hereditários.","option_c":"Condenar o Espírito sem possibilidade de mudança.","option_d":"Substituir a liberdade de escolha.","option_e":"Oferecer experiências de aprendizado, reajuste e desenvolvimento moral.","correct_option":"E","explanation":"As experiências difíceis podem contribuir para o aprendizado e a reparação, sem significar condenação eterna.","reference":"O Livro dos Espíritos, Livro Segundo, cap. VI, questões 258–273.","difficulty":"facil","active":true},{"book":"evangelho","statement":"Qual é o objetivo central de O Evangelho Segundo o Espiritismo, conforme a introdução?","option_a":"Explicar exclusivamente os milagres de Jesus.","option_b":"Reunir uma cronologia completa da vida política de Jesus.","option_c":"Substituir os textos dos Evangelhos.","option_d":"Definir regras administrativas para igrejas.","option_e":"Apresentar um código de moral evangélica e explicar sua aplicação à vida.","correct_option":"E","explanation":"A introdução afirma que a obra se dedica ao ensino moral do Cristo, explicando passagens e suas consequências práticas.","reference":"O Evangelho Segundo o Espiritismo, Introdução, seção I.","difficulty":"facil","active":true},{"book":"evangelho","statement":"Por que Kardec destaca especialmente o ensino moral dos Evangelhos?","option_a":"Porque é exclusivo de um único grupo.","option_b":"Porque elimina a necessidade de reflexão.","option_c":"Porque trata apenas de cerimônias religiosas.","option_d":"Porque não tem relação com a vida cotidiana.","option_e":"Porque é um terreno de encontro entre pessoas de diferentes crenças.","correct_option":"E","explanation":"A introdução apresenta a moral evangélica como um campo comum, capaz de orientar a conduta independentemente de disputas dogmáticas.","reference":"O Evangelho Segundo o Espiritismo, Introdução, seção I.","difficulty":"facil","active":true},{"book":"evangelho","statement":"Segundo a introdução, por que os ensinamentos morais foram agrupados por assunto?","option_a":"Para alterar a mensagem original.","option_b":"Para tornar mais fácil estudar e aplicar os ensinamentos em diferentes situações.","option_c":"Para ocultar a origem das citações.","option_d":"Para organizar uma narrativa cronológica dos milagres.","option_e":"Para eliminar as explicações dos Espíritos.","correct_option":"B","explanation":"Kardec explica que os ensinamentos foram classificados metodicamente por natureza, facilitando a compreensão e a aplicação moral.","reference":"O Evangelho Segundo o Espiritismo, Introdução, seção I.","difficulty":"facil","active":true},{"book":"evangelho","statement":"O que significa o princípio do controle universal do ensino dos Espíritos?","option_a":"Aceitar qualquer comunicação sem exame.","option_b":"Considerar verdadeira apenas a mensagem de um médium famoso.","option_c":"Substituir a razão pela autoridade pessoal.","option_d":"Limitar o estudo a uma única reunião.","option_e":"Verificar a concordância de ensinamentos recebidos espontaneamente por muitos médiuns, em diferentes lugares.","correct_option":"E","explanation":"A introdução apresenta a concordância ampla e independente como garantia importante para os princípios doutrinários.","reference":"O Evangelho Segundo o Espiritismo, Introdução, seção II.","difficulty":"facil","active":true},{"book":"evangelho","statement":"No capítulo I, o que significa a ideia de que Jesus não veio destruir a Lei?","option_a":"Que os ensinamentos morais anteriores seriam abolidos.","option_b":"Que a lei divina deveria ser esquecida.","option_c":"Que toda tradição humana é imutável.","option_d":"Que somente as leis civis têm valor.","option_e":"Que a mensagem de Jesus dá cumprimento e desenvolvimento à lei divina.","correct_option":"E","explanation":"O capítulo explica a continuidade e o cumprimento da lei divina, distinguindo-a de interpretações e práticas humanas transitórias.","reference":"O Evangelho Segundo o Espiritismo, cap. I, itens 1–2.","difficulty":"facil","active":true},{"book":"evangelho","statement":"No capítulo II, a expressão “Meu Reino não é deste mundo” é relacionada principalmente a quê?","option_a":"À ideia de que a vida presente não tem valor moral.","option_b":"À criação de um império político terreno.","option_c":"À rejeição de toda responsabilidade social.","option_d":"À busca de poder econômico.","option_e":"À natureza espiritual do reino anunciado por Jesus.","correct_option":"E","explanation":"O capítulo aborda a vida futura e a natureza espiritual do reino de Jesus, em contraste com os poderes terrenos.","reference":"O Evangelho Segundo o Espiritismo, cap. II, itens 1–3.","difficulty":"facil","active":true},{"book":"evangelho","statement":"O que ensina o capítulo III ao falar das muitas moradas na casa do Pai?","option_a":"Que existe apenas um mundo habitado.","option_b":"Que todos os mundos têm as mesmas condições.","option_c":"Que a vida espiritual é uma metáfora sem realidade.","option_d":"Que a Terra é o destino final de todos os Espíritos.","option_e":"Que a criação comporta diferentes mundos e condições de existência.","correct_option":"E","explanation":"O capítulo relaciona a passagem às diferentes condições dos mundos e ao progresso dos Espíritos.","reference":"O Evangelho Segundo o Espiritismo, cap. III, itens 1–2.","difficulty":"facil","active":true},{"book":"evangelho","statement":"No capítulo IV, a expressão “nascer de novo” é explicada pela obra como referência à quê?","option_a":"A uma mudança de nome durante a vida.","option_b":"À reencarnação, isto é, ao retorno do Espírito à vida corporal.","option_c":"A uma cerimônia pública obrigatória.","option_d":"Ao esquecimento de toda responsabilidade.","option_e":"À ressurreição do mesmo corpo físico.","correct_option":"B","explanation":"O capítulo interpreta o diálogo de Jesus com Nicodemos à luz da reencarnação.","reference":"O Evangelho Segundo o Espiritismo, cap. IV, itens 4–17.","difficulty":"facil","active":true},{"book":"evangelho","statement":"Qual é a orientação principal do capítulo V sobre os aflitos?","option_a":"Evitar qualquer pessoa que sofra.","option_b":"Considerar o sofrimento sempre uma punição definitiva.","option_c":"Buscar apenas compensações materiais.","option_d":"Abandonar toda iniciativa de auxílio.","option_e":"Compreender as aflições à luz da vida futura e da justiça divina, mantendo a confiança e a resignação.","correct_option":"E","explanation":"O capítulo trata das causas atuais e anteriores das aflições e da confiança na justiça divina.","reference":"O Evangelho Segundo o Espiritismo, cap. V, itens 1–13.","difficulty":"facil","active":true},{"book":"evangelho","statement":"Quem é apresentado como o Consolador prometido no capítulo VI?","option_a":"A ausência de dificuldades na vida.","option_b":"Um governante terreno.","option_c":"Uma instituição política.","option_d":"Um sinal de riqueza material.","option_e":"O próprio ensino espiritual que esclarece e consola, associado à missão do Espiritismo.","correct_option":"E","explanation":"O capítulo relaciona a promessa do Consolador à doutrina que esclarece, recorda e desenvolve os ensinamentos de Jesus.","reference":"O Evangelho Segundo o Espiritismo, cap. VI, itens 3–8.","difficulty":"facil","active":true},{"book":"evangelho","statement":"No capítulo VII, o que significa ser “pobre de espírito” na interpretação espírita?","option_a":"Ser intelectualmente incapaz.","option_b":"Desprezar o estudo e o conhecimento.","option_c":"Viver sem buscar aperfeiçoamento.","option_d":"Recusar qualquer responsabilidade.","option_e":"Ser humilde, reconhecer os próprios limites e não se elevar pelo orgulho.","correct_option":"E","explanation":"O capítulo associa a pobreza de espírito à humildade, em oposição ao orgulho e à presunção.","reference":"O Evangelho Segundo o Espiritismo, cap. VII, itens 1–2.","difficulty":"facil","active":true},{"book":"evangelho","statement":"O capítulo VIII associa a pureza de coração principalmente a quê?","option_a":"À aparência externa e às roupas.","option_b":"À simplicidade, sinceridade e retidão das intenções.","option_c":"À ausência de contato com outras pessoas.","option_d":"À riqueza e à posição social.","option_e":"À repetição de fórmulas sem sentimento.","correct_option":"B","explanation":"A pureza de coração é relacionada à simplicidade e à sinceridade interior, não à aparência.","reference":"O Evangelho Segundo o Espiritismo, cap. VIII, itens 1–4.","difficulty":"facil","active":true},{"book":"evangelho","statement":"Qual é o sentido moral de ser manso e pacífico, segundo o capítulo IX?","option_a":"Nunca defender uma pessoa injustiçada.","option_b":"Aceitar a violência como normal.","option_c":"Evitar qualquer diálogo.","option_d":"Cultivar brandura, paciência e respeito, sem alimentar a cólera.","option_e":"Impor silêncio aos demais.","correct_option":"D","explanation":"O capítulo valoriza a mansidão e a paz interior, contrapondo-as à violência e à irritação.","reference":"O Evangelho Segundo o Espiritismo, cap. IX, itens 1–6.","difficulty":"facil","active":true},{"book":"evangelho","statement":"O que caracteriza a misericórdia destacada no capítulo X?","option_a":"Favorecer apenas quem pensa igual.","option_b":"Exigir perfeição dos outros.","option_c":"Punir publicamente todo erro.","option_d":"Ignorar o sofrimento alheio.","option_e":"Perdoar e tratar o próximo com indulgência, reconhecendo as próprias imperfeições.","correct_option":"E","explanation":"O capítulo ensina a indulgência e o perdão, lembrando que todos necessitam de compreensão.","reference":"O Evangelho Segundo o Espiritismo, cap. X, itens 1–4.","difficulty":"facil","active":true},{"book":"evangelho","statement":"Como o capítulo XI orienta a prática do amor ao próximo?","option_a":"Amar apenas quem oferece vantagens.","option_b":"Tratar os outros com justiça, benevolência e respeito, reconhecendo a fraternidade humana.","option_c":"Evitar relações com quem discorda.","option_d":"Confundir amor com aprovação de qualquer atitude.","option_e":"Restringir a caridade à família.","correct_option":"B","explanation":"O capítulo desenvolve o amor ao próximo como princípio de fraternidade e regra de conduta.","reference":"O Evangelho Segundo o Espiritismo, cap. XI, itens 1–4.","difficulty":"facil","active":true},{"book":"evangelho","statement":"No capítulo XII, amar os inimigos significa principalmente o quê?","option_a":"Concordar com todas as ações de quem nos prejudica.","option_b":"Não estabelecer limites diante de abusos.","option_c":"Esquecer a necessidade de justiça.","option_d":"Procurar conflitos para demonstrar coragem.","option_e":"Desejar o bem, não alimentar ódio e responder ao mal sem vingança.","correct_option":"E","explanation":"O capítulo ensina a superar o ódio e a vingança, desejando o bem sem confundir isso com aprovação do mal.","reference":"O Evangelho Segundo o Espiritismo, cap. XII, itens 1–3.","difficulty":"facil","active":true},{"book":"evangelho","statement":"Qual é o ensinamento central do capítulo XIII sobre a caridade?","option_a":"A caridade só tem valor quando é pública.","option_b":"A ajuda deve ser oferecida apenas em troca de reconhecimento.","option_c":"A esmola é a única forma de caridade.","option_d":"A prática do bem deve ser discreta, sem busca de aplauso ou vaidade.","option_e":"A caridade depende do valor financeiro doado.","correct_option":"D","explanation":"O capítulo destaca a discrição na prática do bem e a importância da intenção desinteressada.","reference":"O Evangelho Segundo o Espiritismo, cap. XIII, itens 1–3.","difficulty":"facil","active":true},{"book":"evangelho","statement":"O capítulo XIV, ao tratar de honrar pai e mãe, amplia o dever para incluir o quê?","option_a":"Somente a obediência cega.","option_b":"Respeito, gratidão, cuidado e deveres de amor no ambiente familiar.","option_c":"A obrigação de concordar com toda decisão dos pais.","option_d":"A exclusão dos vínculos de afinidade.","option_e":"A valorização exclusiva da herança.","correct_option":"B","explanation":"O capítulo examina os deveres familiares e distingue laços corporais de vínculos espirituais e afetivos.","reference":"O Evangelho Segundo o Espiritismo, cap. XIV, itens 1–3.","difficulty":"facil","active":true},{"book":"evangelho","statement":"Qual é a máxima que dá título ao capítulo XV?","option_a":"Fora da obediência não há liberdade.","option_b":"Fora da riqueza não há felicidade.","option_c":"Fora do ritual não há progresso.","option_d":"Fora da ciência não há moral.","option_e":"Fora da caridade não há salvação.","correct_option":"E","explanation":"O capítulo apresenta a caridade como princípio essencial da salvação moral, acima de distinções exteriores.","reference":"O Evangelho Segundo o Espiritismo, cap. XV, itens 1–5.","difficulty":"facil","active":true},{"book":"evangelho","statement":"No capítulo XVI, o que representa “Mamon” no ensinamento sobre servir a Deus e às riquezas?","option_a":"A prática da solidariedade.","option_b":"A vida espiritual.","option_c":"A confiança na providência.","option_d":"A simplicidade voluntária.","option_e":"A riqueza material transformada em objeto de apego e culto.","correct_option":"E","explanation":"O capítulo alerta contra a submissão do coração à riqueza e aos interesses materiais.","reference":"O Evangelho Segundo o Espiritismo, cap. XVI, itens 1–3.","difficulty":"facil","active":true},{"book":"evangelho","statement":"O que significa “sede perfeitos” no capítulo XVII?","option_a":"Alcançar perfeição absoluta de imediato.","option_b":"Desistir do aperfeiçoamento porque é impossível.","option_c":"Buscar apenas conhecimento intelectual.","option_d":"Desenvolver as virtudes e aproximar a conduta do exemplo moral de Jesus.","option_e":"Evitar qualquer convivência humana.","correct_option":"D","explanation":"O capítulo trata da perfeição moral possível ao esforço humano, destacando caridade, humildade e amor.","reference":"O Evangelho Segundo o Espiritismo, cap. XVII, itens 1–4.","difficulty":"facil","active":true},{"book":"evangelho","statement":"No capítulo XVIII, a expressão “muitos os chamados e poucos os escolhidos” é relacionada a quê?","option_a":"A privilégios de nascimento.","option_b":"À necessidade de responder ao convite moral com esforço e perseverança.","option_c":"A uma seleção baseada em riqueza.","option_d":"À impossibilidade de transformação pessoal.","option_e":"A uma distinção entre povos.","correct_option":"B","explanation":"O capítulo enfatiza que ouvir o chamado não basta; é necessário viver os ensinamentos.","reference":"O Evangelho Segundo o Espiritismo, cap. XVIII, itens 1–5.","difficulty":"facil","active":true},{"book":"evangelho","statement":"O capítulo XIX ensina que a fé que transporta montanhas está ligada principalmente a quê?","option_a":"À confiança ativa e perseverante, unida à razão e à vontade.","option_b":"À repetição mecânica de palavras.","option_c":"À recusa de toda ação prática.","option_d":"À crença em privilégios pessoais.","option_e":"À ausência de dúvidas em qualquer circunstância.","correct_option":"A","explanation":"A fé é apresentada como força moral que sustenta a ação e o enfrentamento de obstáculos.","reference":"O Evangelho Segundo o Espiritismo, cap. XIX, itens 1–5.","difficulty":"facil","active":true},{"book":"evangelho","statement":"Qual é a lição central da parábola dos trabalhadores da última hora, no capítulo XX?","option_a":"Somente os primeiros a chegar podem receber recompensa.","option_b":"O tempo de serviço é a única medida do valor moral.","option_c":"A justiça divina é arbitrária.","option_d":"A bondade e a misericórdia divinas acolhem quem se dispõe sinceramente ao trabalho do bem.","option_e":"O esforço tardio nunca tem valor.","correct_option":"D","explanation":"A parábola é interpretada em relação à igualdade diante da tarefa espiritual e à misericórdia divina.","reference":"O Evangelho Segundo o Espiritismo, cap. XX, itens 1–3.","difficulty":"facil","active":true},{"book":"evangelho","statement":"O capítulo XXI alerta contra os falsos cristos e falsos profetas por meio de qual critério?","option_a":"A fama e a aparência impressionante.","option_b":"A capacidade de prever acontecimentos.","option_c":"A quantidade de títulos e honrarias.","option_d":"A riqueza dos seguidores.","option_e":"A avaliação dos frutos morais das palavras e das ações.","correct_option":"E","explanation":"O capítulo orienta a reconhecer os verdadeiros ensinamentos pelos frutos e pela coerência moral.","reference":"O Evangelho Segundo o Espiritismo, cap. XXI, itens 1–3.","difficulty":"facil","active":true}]$questions$::jsonb)
  AS x(book text, statement text, option_a text, option_b text, option_c text, option_d text, option_e text, correct_option text, explanation text, reference text, difficulty text, active boolean)
)
